package com.gmail.manhle240406.project.community;
import org.junit.Test;
import static org.junit.Assert.*;
import java.util.*;
import com.google.firebase.Timestamp;
import static com.gmail.manhle240406.project.pet.PetSchema.*;
public class CommunitySafetyTest {
    private final String post="12345678-1234-1234-1234-123456789abc",op="12345678-1234-1234-1234-123456789abd";
    private final Timestamp now=new Timestamp(1000,0);
    private Map<String,Object> root(){return map("schemaVersion",1L,"postId",post,"authorUid","alice","type","community","lifecycle","active","contentVersion",1L,"currentRevisionId","v1","controlVersion",1L,"visibility","hidden","submittedVersion",null,"publicationConsent",false,"moderatorHold","clear","firstPublishedAt",null,"createdAt",now,"updatedAt",now,"lastOperationId",op);}
    @Test public void bodyIsTrimmedBoundedUnicodeAndNonempty(){assertTrue(CommunitySchema.fields(CommunitySchema.fields("🐈".repeat(2000),"cat")));assertFalse(CommunitySchema.fields(CommunitySchema.fields("🐈".repeat(2001),null)));assertFalse(CommunitySchema.fields(CommunitySchema.fields(" ",null)));assertFalse(CommunitySchema.fields(CommunitySchema.fields("\u0001",null)));assertTrue(CommunitySchema.fields(CommunitySchema.fields("Mèo Bông\nĐi dạo",null)));}
    @Test public void mediaPrivateEvidenceAndUnknownFieldsRejected(){for(String key:Arrays.asList("phone","address","chip","reporterUid","provider")){Map<String,Object> f=CommunitySchema.fields("Synthetic story",null);f.put(key,"private");assertFalse(CommunitySchema.fields(f));}assertFalse(CommunitySchema.fields(CommunitySchema.fields("Story","file:///photo")));assertFalse(CommunitySchema.fields(CommunitySchema.fields("Story","https://media.invalid")));}
    @Test public void rootCannotClaimPublicationNewsOrConsent(){assertTrue(CommunitySchema.root(root(),post));for(String key:Arrays.asList("type","visibility","publicationConsent","submittedVersion","schemaVersion")){Map<String,Object> r=root();r.put(key,key.equals("type")?"news":key.equals("visibility")?"community":key.equals("publicationConsent")?true:2L);assertFalse(CommunitySchema.root(r,post));}}
    @Test public void commandFreezesCandidateAndRequiresExactReceiptEquality(){Map<String,Object> f=CommunitySchema.fields("Initial story","dog");CommunityCommand c=new CommunityCommand("create",post,op,0,0,f);f.put("body","Changed story");Map<String,Object> r=map("command","create","postId",post,"operationId",op,"base",c.base(),"input",c.input);assertTrue(c.matches(r));r.put("input",f);assertFalse(c.matches(r));r.put("input",c.input);r.put("base",map("contentVersion",1L,"controlVersion",1L));assertFalse(c.matches(r));}
    @Test public void receiptIsImmutableShapeAndOwnerScoped(){CommunityCommand c=new CommunityCommand("create",post,op,0,0,CommunitySchema.fields("Story",null));Map<String,Object> r=map("schemaVersion",1L,"ownerUid","alice","operationId",op,"postId",post,"command",c.command,"base",c.base(),"result",map("contentVersion",1L,"controlVersion",1L),"input",c.input,"status","committed","committedAt",now);assertTrue(CommunitySchema.receipt(r,"alice",op));assertFalse(CommunitySchema.receipt(r,"bob",op));r.put("privateReview","secret");assertFalse(CommunitySchema.receipt(r,"alice",op));}
    @Test public void onlyScopedPrivateCommandsCanBeIssued(){for(String type:Arrays.asList("publish","submit","like","comment","delete","news")){try{new CommunityCommand(type,post,op,0,0,CommunitySchema.fields("Story",null));fail();}catch(IllegalArgumentException expected){}}try{new CommunityCommand("hide",post,op,0,0,Collections.emptyMap());fail();}catch(IllegalArgumentException expected){}}
    @Test public void gatewayCannotManufactureApprovedReviewerOrReportService(){assertEquals(CommunityGateways.State.UNAVAILABLE,CommunityGateways.REPORT.state());assertEquals(CommunityGateways.State.UNAVAILABLE,CommunityGateways.REVIEW.state());assertFalse(CommunityGateways.publicLoopReady());new CommunityGateways.Target(post,1);try{new CommunityGateways.Target(post,0);fail();}catch(IllegalArgumentException expected){}}
    @Test public void supportedRevisionRejectsPrivateFieldsOrMalformedBody(){Map<String,Object> r=map("schemaVersion",1L,"postId",post,"authorUid","alice","type","community","contentVersion",1L,"body","Story","bundledIllustrationKey",null,"createdAt",now,"operationId",op);assertTrue(CommunitySchema.revision(r,post,1));r.put("body",7L);assertFalse(CommunitySchema.revision(r,post,1));r.put("body","Story");r.put("chip","private");assertFalse(CommunitySchema.revision(r,post,1));}
}
